package com.borislav.freeflow.combat;

import com.borislav.freeflow.network.AnimationPayload;
import net.fabricmc.fabric.api.networking.v1.PlayerLookup;
import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;
import net.minecraft.server.level.ServerPlayer;

import java.util.List;
import java.util.Set;

/**
 * Combat animations (assets/freeflow/player_animations/freeflow_combat.json, generated by
 * tools/gen_animations.py), how strikes pick one, and how hard each one hits.
 */
public final class Anim {
	private Anim() {}

	// Close strikes
	public static final String JAB_RIGHT = "jab_right";
	public static final String JAB_LEFT = "jab_left";
	public static final String HOOK_RIGHT = "hook_right";
	public static final String HOOK_LEFT = "hook_left";
	public static final String ELBOW = "elbow";
	public static final String KNEE = "knee";
	public static final String FRONT_KICK = "front_kick";
	public static final String ROUNDHOUSE = "roundhouse";
	public static final String SPIN_BACKFIST = "spin_backfist";
	public static final String HAYMAKER = "haymaker";
	// Lunging strikes
	public static final String FLYING_KICK = "flying_kick";
	public static final String FLYING_KNEE = "flying_knee";
	// Beatdown / finisher
	public static final String BEATDOWN_RIGHT = "beatdown_right";
	public static final String BEATDOWN_LEFT = "beatdown_left";
	public static final String FINISHER = "finisher";
	// Other moves
	public static final String COUNTER = "counter";
	public static final String STUN = "stun";
	public static final String EVADE = "evade";
	public static final String VAULT = "vault";
	public static final String GROUND_TAKEDOWN = "ground_takedown";
	public static final String SPECIAL_TAKEDOWN = "special_takedown";

	public static final List<String> ALL = List.of(JAB_RIGHT, JAB_LEFT, HOOK_RIGHT, HOOK_LEFT, ELBOW, KNEE, FRONT_KICK,
			ROUNDHOUSE, SPIN_BACKFIST, HAYMAKER, FLYING_KICK, FLYING_KNEE, BEATDOWN_RIGHT, BEATDOWN_LEFT, FINISHER,
			COUNTER, STUN, EVADE, VAULT, GROUND_TAKEDOWN, SPECIAL_TAKEDOWN);

	/** Combo strings: the flow gets flashier as the combo grows. */
	private static final List<String> TIER_LOW = List.of(JAB_RIGHT, JAB_LEFT, HOOK_RIGHT, FRONT_KICK);
	private static final List<String> TIER_MID = List.of(HOOK_LEFT, HOOK_RIGHT, ELBOW, KNEE, ROUNDHOUSE);
	private static final List<String> TIER_HIGH = List.of(HOOK_RIGHT, SPIN_BACKFIST, KNEE, HAYMAKER, ELBOW, ROUNDHOUSE);

	/** Lunges at least this many ticks long become flying attacks. */
	public static final int FLYING_TRAVEL_TICKS = 3;

	public static final int LIGHT = 1;
	public static final int MEDIUM = 2;
	public static final int HEAVY = 3;

	private static final Set<String> HEAVY_MOVES = Set.of(ROUNDHOUSE, SPIN_BACKFIST, HAYMAKER, FLYING_KICK, FLYING_KNEE,
			FINISHER, SPECIAL_TAKEDOWN, GROUND_TAKEDOWN);
	private static final Set<String> LIGHT_MOVES = Set.of(JAB_RIGHT, JAB_LEFT, BEATDOWN_RIGHT, BEATDOWN_LEFT);

	/** Picks the strike animation from the lunge length and the combo tier. */
	public static String chooseStrike(int index, int travelTicks, int combo) {
		if (travelTicks >= FLYING_TRAVEL_TICKS) {
			return index % 2 == 0 ? FLYING_KICK : FLYING_KNEE;
		}
		List<String> tier = combo >= 10 ? TIER_HIGH : combo >= 5 ? TIER_MID : TIER_LOW;
		return tier.get(Math.floorMod(index, tier.size()));
	}

	public static String beatdown(int index) {
		return index % 2 == 0 ? BEATDOWN_RIGHT : BEATDOWN_LEFT;
	}

	/** Hit strength of a move: LIGHT, MEDIUM or HEAVY (drives damage, knockback and impact effects). */
	public static int strength(String move) {
		if (HEAVY_MOVES.contains(move)) {
			return HEAVY;
		}
		return LIGHT_MOVES.contains(move) ? LIGHT : MEDIUM;
	}

	/** Plays the animation on {@code player} for the player and everyone tracking them. */
	public static void play(ServerPlayer player, String name) {
		AnimationPayload payload = new AnimationPayload(player.getId(), name);
		if (ServerPlayNetworking.canSend(player, AnimationPayload.TYPE)) {
			ServerPlayNetworking.send(player, payload);
		}
		for (ServerPlayer other : PlayerLookup.tracking(player)) {
			if (other != player && ServerPlayNetworking.canSend(other, AnimationPayload.TYPE)) {
				ServerPlayNetworking.send(other, payload);
			}
		}
	}
}
